// Removes the local git hooks generated by scripts/install-git-hooks.mjs.
import { execFileSync } from 'node:child_process';
import { rmSync } from 'node:fs';
import { join } from 'node:path';

const HOOK_NAMES = ['pre-commit', 'pre-push'];

const hooksDir = execFileSync('git', ['rev-parse', '--git-path', 'hooks'], {
  encoding: 'utf8',
}).trim();

for (const name of HOOK_NAMES) {
  try {
    rmSync(join(hooksDir, name));
  } catch {
    // Hook was not installed; ignore.
  }
}

console.log('Local git hooks removed.');
